    if 'serviceName' in metric_df.columns:
        app_metrics_df = metric_df[['serviceName', 'startTime', 'avg_time', 'num', 'succee_num', 'succee_rate']].copy()
    else:
        app_metrics_df = pd.DataFrame()

    if 'name' in metric_df.columns and 'cmdb_id' in metric_df.columns:
        other_metrics_df = metric_df[['name', 'cmdb_id']].copy()
    else:
        other_metrics_df = pd.DataFrame()

    # For app metrics, KPIs are fixed: startTime, avg_time, num, succee_num, succee_rate
    # Components are serviceName
    if not app_metrics_df.empty:
        app_kpis = ['startTime', 'avg_time', 'num', 'succee_num', 'succee_rate']
        app_components = app_metrics_df['serviceName'].unique()
        app_summary = pd.DataFrame({
            'metric_file': ['app_metrics'],
            'unique_kpi_names': [app_kpis],
            'unique_components': [list(app_components)]
        })
    else:
        app_summary = pd.DataFrame()

    # For other metrics, KPIs are unique 'name' values, components are unique 'cmdb_id' values
    if not other_metrics_df.empty:
        other_kpis = other_metrics_df['name'].unique()
        other_components = other_metrics_df['cmdb_id'].unique()
        other_summary = pd.DataFrame({
            'metric_file': ['node_container_service_metrics'],
            'unique_kpi_names': [list(other_kpis)],
            'unique_components': [list(other_components)]
        })
    else:
        other_summary = pd.DataFrame()

    # Combine summaries
    kpi_component_summary = pd.concat([app_summary, other_summary], ignore_index=True)

